// Metro and city codes that cover more than one airport.
export const METRO = {"LON": ["LHR", "LGW", "STN", "LTN", "LCY", "SEN"], "NYC": ["JFK", "LGA", "EWR"], "PAR": ["CDG", "ORY", "BVA"], "MIL": ["MXP", "LIN", "BGY"], "ROM": ["FCO", "CIA"], "TYO": ["HND", "NRT"], "WAS": ["IAD", "DCA", "BWI"], "CHI": ["ORD", "MDW"], "STO": ["ARN", "BMA", "NYO"], "YTO": ["YYZ", "YTZ"], "YMQ": ["YUL"], "BER": ["BER"], "MOW": ["SVO", "DME", "VKO"], "SEL": ["ICN", "GMP"], "OSA": ["KIX", "ITM"], "BJS": ["PEK", "PKX"], "SHA": ["PVG", "SHA"], "BUE": ["EZE", "AEP"], "SAO": ["GRU", "CGH", "VCP"], "RIO": ["GIG", "SDU"], "JKT": ["CGK", "HLP"], "BKK": ["BKK", "DMK"], "IST": ["IST", "SAW"], "DXB": ["DXB", "DWC"], "REK": ["KEF", "RKV"], "BRU": ["BRU", "CRL"], "OSL": ["OSL", "TRF"], "VCE": ["VCE", "TSF"], "GLA": ["GLA", "PIK"], "BFS": ["BFS", "BHD"], "TCI": ["TFS", "TFN"], "DTT": ["DTW"], "QDF": ["DFW", "DAL"], "HOU": ["IAH", "HOU"]};

let cache = null;

export function loadAirports() {
  if (cache) return cache;
  const list = [];
  const byCode = new Map();
  for (const line of RAW.split('\n')) {
    const [code, name, city, country, lat, lon, size, extra] = line.split('|');
    const a = { code, name, city, country, lat: +lat, lon: +lon, large: size === 'L', extra: extra || '' };
    list.push(a);
    byCode.set(code, a);
  }
  cache = { list, byCode };
  return cache;
}

export function airportByCode(code) {
  return loadAirports().byCode.get(String(code || '').toUpperCase()) || null;
}

export function countryName(cc) {
  return COUNTRIES[cc] || cc;
}
